 & Schema-informed & 5.8 & 0.3 & \textbf{0.0} & --- \\
\midrule
\multirow{2}{*}{DocRED} & Unconstrained & 18.7 & 28.9 & 7.5 & 0.1 \\
 & Schema-informed & 12.8 & 18.4 & 0.6 & 0.2 \\
